import pytest
from marshmallow import Schema, fields, pre_load, post_load, pre_dump, post_dump, validates_schema

def test_pass_collection_instead_of_pass_many():
    class MySchema(Schema):
        x = fields.Int()

        @post_load(pass_collection=True)
        def make_obj(self, data, many, **kwargs):
            return data

    schema = MySchema(many=True)
    res = schema.load([{"x": 1}])
    assert res == [{"x": 1}]

